// AUTO-GENERATED — do not edit by hand.
// sRGB -> CMYK lookup tables baked from the Adobe ICC profiles with littleCMS
// (Relative Colorimetric + Black Point Compensation), i.e. the same conversion
// Illustrator/Photoshop perform when you paste an RGB color into a CMYK document.
// Regenerate with scripts/build_cmyk_lut.py.
//
// Layout: a GRID^3 cube, R slowest -> B fastest, 4 bytes per cell (C,M,Y,K, 0-255).

export const GRID = 33;

export type CmykProfileKey = 'swop' | 'fogra39' | 'gracol';

export const CMYK_PROFILES: { key: CmykProfileKey; label: string }[] = [
  { key: 'swop', label: 'U.S. Web Coated (SWOP) v2' },
  { key: 'fogra39', label: 'Coated FOGRA39' },
  { key: 'gracol', label: 'Coated GRACoL 2006' },
];

const B64: Record<CmykProfileKey, string> = {
  swop: '',
  fogra39: '',
  gracol: '',
};

const cache: Partial<Record<CmykProfileKey, Uint8Array>> = {};

export const getCmykLut = (profile: CmykProfileKey): Uint8Array => {
  const hit = cache[profile];
  if (hit) return hit;
  const bin = atob(B64[profile]);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  cache[profile] = arr;
  return arr;
};
